using HelpDesk.Api.Application.Ai;using HelpDesk.Api.Application.Common.Exceptions;using HelpDesk.Api.Application.Tickets;using HelpDesk.Api.Contracts.Ai;
namespace HelpDesk.Api.Infrastructure.Ai;
public sealed class AiTicketAnalysisService(ITicketService tickets,ITicketLookupService lookups,IAiTicketProvider provider):IAiTicketAnalysisService
{public async Task<AiTicketAnalysisResponse>AnalyzeTicketAsync(Guid ticketId,TicketAccessContext access,CancellationToken cancellationToken=default){if(ticketId==Guid.Empty)throw new TicketNotFoundException();if(access is null||access.UserId==Guid.Empty)throw new TicketAccessDeniedException();var ticket=await tickets.GetByIdAsync(ticketId,access,cancellationToken);var categories=(await lookups.GetCategoriesAsync(cancellationToken)).Where(x=>x.IsActive).ToArray();var priorities=(await lookups.GetPrioritiesAsync(cancellationToken)).Where(x=>x.IsActive).ToArray();var raw=await provider.AnalyzeAsync(new(ticket.Title,ticket.Description,categories.Select(x=>x.Name).ToArray(),priorities.Select(x=>x.Name).ToArray()),cancellationToken);var category=categories.FirstOrDefault(x=>string.Equals(x.Name,raw.RecommendedCategoryName?.Trim(),StringComparison.OrdinalIgnoreCase));var priority=priorities.FirstOrDefault(x=>string.Equals(x.Name,raw.RecommendedPriorityName?.Trim(),StringComparison.OrdinalIgnoreCase));return new(){Summary=Bound(raw.Summary,1000),RecommendedCategoryId=category?.Id,RecommendedCategoryName=category?.Name,RecommendedPriorityId=priority?.Id,RecommendedPriorityName=priority?.Name,TroubleshootingSuggestions=raw.TroubleshootingSuggestions.Where(x=>!string.IsNullOrWhiteSpace(x)).Take(5).Select(x=>Bound(x,500)).ToArray()};}
private static string Bound(string?value,int length){var text=(value??string.Empty).Trim();return text.Length<=length?text:text[..length];}}
